 void showRotinaLogin(){
  LinearLayout layout=column();
  EditText identifier=input("Usuário ou e-mail do Rotina360",false);
  EditText password=input("Senha do Rotina360",false);
  password.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);
  layout.addView(identifier);layout.addView(password);
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Entrar com Rotina360").setView(layout)
    .setNegativeButton("Cancelar",null).setPositiveButton("Entrar",null).create();
  dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{
    String username=identifier.getText().toString().trim();
    String pass=password.getText().toString();
    if(username.isEmpty()||pass.isEmpty()){identifier.setError("Informe usuário e senha");return;}
    dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);
    RotinaAuth.login(username,pass,(session,error)->{
      if(isFinishing()||isDestroyed())return;
      dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);
      if(session==null){toast(error==null?"Não foi possível entrar.":error);return;}
      try{SecureSession.save(this,session);dialog.dismiss();toast("Login confirmado. Sincronização ainda não habilitada.");}
      catch(Exception ex){toast("Não foi possível proteger a sessão neste aparelho.");}
    });
  }));
  dialog.show();
 }
 void showPage(int tab){
  activeTab=tab;
  if(countPage==null||historyPage==null||accountPage==null||revisionPage==null)return;
  countPage.setVisibility(tab==0?View.VISIBLE:View.GONE);
  historyPage.setVisibility(tab==1?View.VISIBLE:View.GONE);
  revisionPage.setVisibility(tab==2?View.VISIBLE:View.GONE);
  accountPage.setVisibility(tab==3?View.VISIBLE:View.GONE);
  if(screenScroll!=null)screenScroll.post(()->screenScroll.scrollTo(0,0));
 }
 void openFabMenu(View anchor){
  PopupMenu popup=new PopupMenu(this,anchor,Gravity.END);
  final String[] options={"Contagem","Histórico","Revisão de local","Conta"};
  for(int index=0;index<options.length;index++)popup.getMenu().add(0,index,index,options[index]);
  popup.setOnMenuItemClickListener(option->{showPage(option.getItemId());return true;});
  popup.show();
 }
 void updateRevisionStatus(){
  if(revisionStatus==null)return;
  if(revisionLocal.isEmpty())revisionStatus.setText("Bipe ou informe o local a revisar.");
  else revisionStatus.setText("Local: "+revisionLocal+"\nRegistros atuais: "+LocationRevision.previous(db,revisionLocal)+"\nItens rebipados: "+LocationRevision.count(db,revisionLocal)
    +(revisionMode?"\nRevisão em andamento: as contagens novas estão em rascunho.":"\nInicie a revisão para recontar."));
 }
 void beginRevision(){
  if(revisionMode&&!revisionLocal.equals(LocationCatalog.normalize(revisionInput.getText().toString()))){toast("Conclua ou descarte a revisão atual antes de mudar de local.");return;}
  String location=LocationCatalog.normalize(revisionInput.getText().toString());
  if(locations==null||!locations.contains(location)){revisionInput.setError("Local não cadastrado");return;}
  revisionLocal=location;revisionMode=true;local.setText(location);keep.setChecked(true);
  updateRevisionStatus();showPage(0);item.requestFocus();
  toast("Revisão iniciada. Bipe todos os itens deste local.");
 }
 void showRevisionDraft(){
  if(!revisionMode||revisionLocal.isEmpty()){toast("Inicie uma revisão.");return;}
  StringBuilder lines=new StringBuilder();
  try(Cursor c=db.rawQuery("SELECT item,quantidade,unidade,total_pc FROM inv_anual_revisao_rascunho WHERE local=? ORDER BY id",new String[]{revisionLocal})){
    while(c.moveToNext()){
     if(lines.length()>0)lines.append("\n");
     lines.append(c.getString(0)).append(" — ").append(c.getString(1)).append(" ").append(c.getString(2)==null?"PC":c.getString(2));
     if(c.getString(3)!=null)lines.append(" (").append(c.getString(3)).append(" PC)");
    }
  }
  new AlertDialog.Builder(this).setTitle("Revisão • "+revisionLocal)
   .setMessage(lines.length()==0?"Nenhum item rebipado.":lines.toString())
   .setPositiveButton("Fechar",null).show();
 }
 void finishRevision(){
  if(!revisionMode||revisionLocal.isEmpty()){toast("Inicie uma revisão primeiro.");return;}
  int before=LocationRevision.previous(db,revisionLocal),after=LocationRevision.count(db,revisionLocal);
  if(after<1){toast("Bipe ao menos um item antes de confirmar.");return;}
  new AlertDialog.Builder(this).setTitle("Substituir TODAS as contagens do local?")
   .setMessage("Local: "+revisionLocal+"\nContagens anteriores: "+before+"\nNovas contagens: "+after+
    "\n\nItens não rebipados serão removidos da contagem ativa deste local. Confira todos os itens antes de confirmar. O histórico de eventos será preservado.")
   .setNegativeButton("Voltar",null).setPositiveButton("Confirmar revisão",(d,w)->{
    try{LocationRevision.replace(db,revisionLocal);revisionMode=false;revisionLocal="";revisionInput.setText("");
     clear();refresh();updateRevisionStatus();showPage(2);toast("Revisão concluída. Contagens substituídas.");
    }catch(Exception e){toast("Falha ao aplicar revisão. Dados anteriores preservados.");}
   }).show();
 }
 void cancelRevision(){
  if(!revisionMode)return;
  new AlertDialog.Builder(this).setTitle("Cancelar revisão?")
   .setMessage("Descartar os itens rebipados neste rascunho? As contagens originais permanecerão intactas.")
   .setNegativeButton("Continuar",null).setPositiveButton("Descartar",(d,w)->{
    LocationRevision.discard(db,revisionLocal);revisionLocal="";revisionMode=false;revisionInput.setText("");
    clear();updateRevisionStatus();showPage(2);
   }).show();
 }
